import React from 'react';
import { FormModal, FormItem, FormLayout, Input } from '@storage-fe/formily-arco';
import { createSchemaField } from '@formily/react';
import { Button } from '@arco-design/web-react';

const SchemaField = createSchemaField({
  components: {
    FormItem,
    Input,
  },
});

const schema = {
  type: 'object',
  properties: {
    aaa: {
      type: 'string',
      title: '输入框1',
      required: true,
      'x-decorator': 'FormItem',
      'x-component': 'Input',
    },
    bbb: {
      type: 'string',
      title: '输入框2',
      required: true,
      'x-decorator': 'FormItem',
      'x-component': 'Input',
    },
    ccc: {
      type: 'string',
      title: '输入框3',
      required: true,
      'x-decorator': 'FormItem',
      'x-component': 'Input',
    },
    ddd: {
      type: 'string',
      title: '输入框4',
      required: true,
      'x-decorator': 'FormItem',
      'x-component': 'Input',
    },
  },
};

export default () => (
  <FormModal.Portal>
    <Button
      onClick={() => {
        const dialog = FormModal('弹窗表单', () => (
          <FormLayout labelCol={6} wrapperCol={10}>
            <SchemaField schema={schema} />
            <FormModal.FooterLeft>
              <span
                onClick={() => {
                  dialog.close();
                }}
                style={{ marginLeft: 4 }}
              >
                扩展文案(点击关闭弹窗)
              </span>
            </FormModal.FooterLeft>
          </FormLayout>
        ));
        dialog
          .forOpen((payload, next) => {
            setTimeout(() => {
              next({
                initialValues: {
                  aaa: '123',
                },
              });
            }, 1000);
          })
          .forConfirm((payload, next) => {
            setTimeout(() => {
              console.log(payload);
              next(payload);
            }, 1000);
          })
          .forCancel((payload, next) => {
            setTimeout(() => {
              console.log(payload);
              next(payload);
            }, 1000);
          })
          .open()
          .then(console.log);
      }}
    >
      点我打开表单
    </Button>
  </FormModal.Portal>
);
